/* Recovery rebuild: native snapshots and project-local transactional clipboard. */
(() => {
'use strict';
const MIME='application/x-forkwise',clone=v=>JSON.parse(JSON.stringify(v));
let cutSession=null,pointer=null,sequence={key:'',count:0};
const fw=()=>window.FW,project=()=>fw().project();
function isBlocked(event){return event.isComposing||window.FWCanvas.isCropping?.()||event.target.closest('input,textarea,[contenteditable=true],#modalHost,.fw-dialog-backdrop,.popover')||document.querySelector('#modalHost')?.children.length||document.querySelector('.fw-dialog-backdrop');}
function descendants(ids,nodes){const set=new Set(ids);let changed=true;while(changed){changed=false;for(const n of nodes)if((set.has(n.groupId)||set.has(n.parentId))&&!set.has(n.id)){set.add(n.id);changed=true;}}return set;}
function snapshot(){FWCanvas.finishEdit();FWPanels.flush?.();const p=project(),ids=descendants(fw().state.selected,p.nodes),nodes=clone(p.nodes.filter(n=>ids.has(n.id))),edges=p.edges.filter(e=>ids.has(e.id)||(ids.has(e.from)&&ids.has(e.to))).map(e=>{const q=FWCanvas.endpoints(e);return {...clone(e),start:q.a,end:q.b};});return {version:2,copyId:fw().uid(),sourceProject:p.id,nodes,edges,tags:clone(p.tags)};}
function write(event,data){try{event.clipboardData.setData(MIME,JSON.stringify(data));event.clipboardData.setData('text/plain',data.nodes.map(n=>n.type==='card'?[n.title,n.body].filter(Boolean).join('\n'):n.type==='video'?n.url||n.title||'':n.title||'').join('\n\n'));event.preventDefault();return true;}catch{fw().toast('无法写入剪贴板，原对象未移除');return false;}}
function onCopy(event){if(isBlocked(event)||!fw().state.selected.length)return;const data=snapshot();if(write(event,data)){cutSession=null;sequence.key='';fw().toast('已复制所选对象');}}
function onCut(event){if(isBlocked(event)||!fw().state.selected.length)return;const data=snapshot(),token=fw().uid();data.cutToken=token;if(!write(event,data))return;const ids=new Set(data.nodes.map(n=>n.id)),edges=project().edges.filter(e=>ids.has(e.from)||ids.has(e.to)||fw().state.selected.includes(e.id)).map(e=>{const q=FWCanvas.endpoints(e);return {...clone(e),start:q.a,end:q.b};});cutSession={token,sourceProject:project().id,data:clone(data),edges};sequence.key='';FWCanvas.remove();fw().toast('已剪切 · 可撤销恢复');}
function pastePosition(copyId){const root=document.getElementById('canvasEngine'),box=root.getBoundingClientRect(),v=fw().state.viewport;const at=pointer&&pointer.x>=box.left&&pointer.x<=box.right&&pointer.y>=box.top&&pointer.y<=box.bottom?{x:(pointer.x-box.left-v.x)/v.zoom,y:(pointer.y-box.top-v.y)/v.zoom}:FWCanvas.center();const key=[project().id,copyId,at.x.toFixed(1),at.y.toFixed(1),v.x,v.y,v.zoom].join('|');sequence=key===sequence.key?{key,count:sequence.count+1}:{key,count:0};return{x:at.x+24*sequence.count,y:at.y+24*sequence.count};}
function bounds(data){const rects=data.nodes.map(n=>({x:n.x,y:n.y,w:n.w,h:n.h}));data.edges.forEach(e=>{rects.push({x:e.start.x,y:e.start.y,w:0,h:0},{x:e.end.x,y:e.end.y,w:0,h:0});});return{x:Math.min(...rects.map(r=>r.x)),y:Math.min(...rects.map(r=>r.y))};}
function cleanHTML(html){const box=document.createElement('div');box.innerHTML=html;box.querySelectorAll('script,iframe,object,embed,style,link,meta').forEach(el=>el.remove());box.querySelectorAll('*').forEach(el=>{[...el.attributes].forEach(a=>{if(/^on/i.test(a.name)||(/^(href|src|xlink:href)$/i.test(a.name)&&/^\s*javascript:/i.test(a.value)))el.removeAttribute(a.name);});});return box.innerHTML;}
function validData(raw){if(!raw||raw.version!==2||!Array.isArray(raw.nodes)||!Array.isArray(raw.edges)||!Array.isArray(raw.tags))return null;const data=clone(raw),types=new Set(['card','text','shape','image','video','stroke','frame','group']);if(data.nodes.some(n=>!n.id||!types.has(n.type)||![n.x,n.y,n.w,n.h].every(Number.isFinite))||data.edges.some(e=>!e.id||!e.start||!e.end||![e.start.x,e.start.y,e.end.x,e.end.y].every(Number.isFinite)))return null;for(const n of data.nodes){if(n.bodyHtml)n.bodyHtml=cleanHTML(n.bodyHtml);if(n.html)n.html=cleanHTML(n.html);}return data;}
function tokenConsumed(token){return fw().data.projects.some(p=>(p.clipboardMoves||[]).includes(token));}
function pasteData(raw,at){const data=validData(raw);if(!data||(!data.nodes.length&&!data.edges.length))return false;const p=project(),b=bounds(data);at||=pastePosition(data.copyId||JSON.stringify(data));const dx=at.x-b.x,dy=at.y-b.y,knownCut=cutSession&&data.cutToken===cutSession.token,originalsExist=data.nodes.some(n=>p.nodes.some(a=>a.id===n.id))||data.edges.some(e=>p.edges.some(a=>a.id===e.id)),firstMove=knownCut&&!tokenConsumed(data.cutToken)&&!originalsExist,restore=firstMove&&p.id===cutSession.sourceProject;
fw().transact(restore?'粘贴剪切对象':'粘贴对象',target=>{
const map=new Map(data.nodes.map(n=>[n.id,restore?n.id:fw().uid()]));
const nodes=data.nodes.map(n=>({...clone(n),id:map.get(n.id),x:n.x+dx,y:n.y+dy,groupId:map.get(n.groupId)||null,parentId:map.get(n.parentId)||null}));
for(const n of nodes){if(!restore)delete n.attachment;else if(n.attachment&&!map.has(n.attachment.targetId)&&!data.edges.some(e=>e.id===n.attachment.targetId)){n.attachment.offsetX+=dx;n.attachment.offsetY+=dy;}}
for(const n of nodes)n.tags=(n.tags||[]).map(id=>{const source=data.tags.find(t=>t.id===id);if(!source)return null;let tag=target.tags.find(t=>t.name.trim().toLocaleLowerCase()===source.name.trim().toLocaleLowerCase());if(!tag){tag={...clone(source),id:fw().uid()};target.tags.push(tag);}return tag.id;}).filter(Boolean);
const targetIds=new Set([...target.nodes.map(n=>n.id),...nodes.map(n=>n.id)]),sourceEdges=restore?cutSession.edges:data.edges;
const edges=sourceEdges.filter(e=>!restore||((!e.from||targetIds.has(e.from))&&(!e.to||targetIds.has(e.to)))).map(e=>{const from=map.get(e.from)||(restore?e.from:null),to=map.get(e.to)||(restore?e.to:null);return{...clone(e),id:restore?e.id:fw().uid(),from,to,start:{x:e.start.x+dx,y:e.start.y+dy},end:{x:e.end.x+dx,y:e.end.y+dy}};});
target.nodes.push(...nodes);target.edges.push(...edges);FWCanvas.updateFrames?.(nodes.map(n=>n.id));if(firstMove){target.clipboardMoves||=[];target.clipboardMoves.push(data.cutToken);}fw().state.selected=[...nodes.filter(n=>!n.groupId&&!nodes.some(a=>a.id===n.parentId)).map(n=>n.id),...edges.filter(e=>!e.from&&!e.to).map(e=>e.id)];});return true;}
function onPaste(event){if(isBlocked(event))return;const file=[...event.clipboardData.items].find(item=>item.type.startsWith('image/'))?.getAsFile();if(file){event.preventDefault();FWCanvas.addImage(file);return;}const internal=event.clipboardData.getData(MIME);if(internal){try{if(pasteData(JSON.parse(internal))){event.preventDefault();return;}}catch{fw().toast('无法读取这份画布剪贴板，原内容未改变');event.preventDefault();return;}}let text=event.clipboardData.getData('text/plain');if(!text)return;const sharedURL=window.FWVideo?.extractLink?.(text);if(sharedURL)text=sharedURL;if(window.FWVideo?.acceptsLink(text)){event.preventDefault();window.FWVideo.addLink(text,pastePosition('video:'+text));return;}event.preventDefault();const at=pastePosition('text:'+text);fw().transact('粘贴文字为卡片',p=>{const n={id:fw().uid(),type:'card',x:at.x,y:at.y,w:286,h:180,title:'',body:text,tags:[],color:'#ffffff'};p.nodes.push(n);FWCanvas.updateFrames?.([n.id]);fw().state.selected=[n.id];});}
function init(){document.addEventListener('pointermove',event=>{pointer={x:event.clientX,y:event.clientY};});document.addEventListener('copy',onCopy);document.addEventListener('cut',onCut);document.addEventListener('paste',onPaste);}
window.FWClipboard={init,pasteData,snapshot,resetSequence:()=>{sequence.key='';}};
})();
